import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Form Error Message","description":"","frontmatter":{"prev":{"text":"Current Entry as Saved","link":"/documentation/field-types/advance/current-entry-as-saved"},"next":{"text":"Check Downloads","link":"/documentation/field-types/browser-actions/check-downloads"}},"headers":[],"relativePath":"documentation/field-types/advance/form-error-message.md","filePath":"documentation/field-types/advance/form-error-message.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/advance/form-error-message.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="form-error-message" tabindex="-1">Form Error Message <a class="header-anchor" href="#form-error-message" aria-label="Permalink to “Form Error Message”">​</a></h1><p>The <strong>Form Error Message</strong> field type detects on-screen validation or server errors after form interaction without requiring URL redirection or page change matching.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Key Difference from Form Error Response</strong>: Unlike <a href="/documentation/form-response/form-error-response.html">Form Error Response</a>, this field type detects in-page error alerts, banners, or DOM messages on the current URL without requiring &quot;Error Page URL&quot; rules.</p></div><hr><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to “When to Use”">​</a></h2><p>Use this field type when:</p><ul><li>Forms display error messages dynamically via JavaScript on the same page (e.g., &quot;Email already registered&quot;, &quot;Invalid OTP&quot;, or &quot;Server Timeout&quot;).</li><li>Errors can appear in varying locations across the page (top notifications, inline alerts, or modal popups).</li><li>You want to record the exact error message into your <code>.xlsx</code> row record or halt automation safely.</li></ul><hr><h2 id="field-options" tabindex="-1">Field Options <a class="header-anchor" href="#field-options" aria-label="Permalink to “Field Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Error Response Type</strong></td><td>Detection mode used to locate the error (Page text, Alert dialog, Input value, or Element existence).</td></tr><tr><td><strong>Enter Error Message</strong></td><td>Target text strings or patterns to identify error states.</td></tr><tr><td><strong>Entry Action Type</strong></td><td>Whether to halt automation immediately (<code>Stop Entry</code>) or record the message into the spreadsheet (<code>Save Error in the Entry Data</code>).</td></tr><tr><td><strong>Delay Time Before Run Action</strong></td><td>Timeout in milliseconds before executing the follow-up recovery action.</td></tr><tr><td><strong>Action</strong></td><td>Operation to trigger upon error detection (Redirect, Reload, Re-Execute, Click, or Segment).</td></tr></tbody></table><hr><h2 id="additional-options" tabindex="-1">Additional Configuration Options <a class="header-anchor" href="#additional-options" aria-label="Permalink to “Additional Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>If excel data is not found then don&#39;t execute the action</strong></td><td>Disables follow-up action if spreadsheet data is not present.</td></tr><tr><td><strong>If last excel entry completed then don&#39;t execute the action</strong></td><td>Prevents execution if the error occurs on the final dataset row.</td></tr><tr><td><strong>If there is no Excel data, update only scraper data in Excel</strong></td><td>Restricts workbook updates to scraper outputs.</td></tr><tr><td><strong>Can error message be anything in this element</strong></td><td>Wildcard mode matching any error text found inside the specified element.</td></tr><tr><td><strong>Remove excel column value from current entry?</strong></td><td>Clears the value from memory once processed.</td></tr><tr><td><strong>Set custom message after error message matched?</strong></td><td>Logs a custom status phrase instead of the raw DOM error text.</td></tr></tbody></table><hr><h2 id="error-response-type" tabindex="-1">Error Response Types <a class="header-anchor" href="#error-response-type" aria-label="Permalink to “Error Response Types”">​</a></h2><h3 id="matching-message-in-page" tabindex="-1">1. Matching Message In Page <a class="header-anchor" href="#matching-message-in-page" aria-label="Permalink to “1. Matching Message In Page”">​</a></h3><p>Scans the page body or a designated container element for matching error text.</p><ul><li><strong>Message Selector Query</strong> <em>(Optional)</em>: Limits the search to a specific alert box or validation container.</li></ul><img src="/image/entry-response-08.png" alt="Error Message on Page" style="max-width:480px;border-radius:8px;margin:16px 0;"><hr><h3 id="matching-message-in-alert" tabindex="-1">2. Matching Message In Browser Alert <a class="header-anchor" href="#matching-message-in-alert" aria-label="Permalink to “2. Matching Message In Browser Alert”">​</a></h3><p>Detects error alerts triggered via JavaScript <code>alert()</code> popups.</p><img src="/image/entry-response-09.png" alt="Alert Dialog Error Detection" style="max-width:450px;border-radius:8px;margin:16px 0;"><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Enable <strong>Hide JavaScript Dialog</strong> in <a href="/documentation/settings.html#hide-javascript-dialog">Extension Settings</a> to suppress alert popups automatically.</p></div><hr><h3 id="matching-message-in-element-value" tabindex="-1">3. Matching Message In Page Element Value <a class="header-anchor" href="#matching-message-in-element-value" aria-label="Permalink to “3. Matching Message In Page Element Value”">​</a></h3><p>Checks the <code>value</code> attribute of input or status fields for error text.</p><img src="/image/entry-response-06.png" alt="Element Value Error Check" style="max-width:480px;border-radius:8px;margin:16px 0;"><hr><h3 id="checking-element-exists" tabindex="-1">4. Checking Element Exists In Page <a class="header-anchor" href="#checking-element-exists" aria-label="Permalink to “4. Checking Element Exists In Page”">​</a></h3><p>Flags an error as soon as a designated error element mounts into the DOM.</p><ul><li><strong>Required Parameter</strong>: <code>Message Selector Query</code> targeting the error banner or badge (e.g., <code>.form-error-toast</code>).</li></ul><hr><h2 id="enter-error-message" tabindex="-1">Enter Error Message <a class="header-anchor" href="#enter-error-message" aria-label="Permalink to “Enter Error Message”">​</a></h2><p>Specify the error message strings to match. You can configure multiple phrases; if any phrase matches, the error flow is activated.</p><ul><li><strong>Spreadsheet Variables</strong>: Use dynamic variables like <code>Error: {$Email$} is already registered</code>.</li><li><strong>Partial Matching</strong>: Providing <code>&quot;already registered&quot;</code> matches any longer sentence containing that substring.</li></ul><img src="/image/entry-response-10.png" alt="Error Messages Configuration" style="max-width:480px;border-radius:8px;margin:16px 0;"><hr><h2 id="entry-action-type" tabindex="-1">Entry Action Type <a class="header-anchor" href="#entry-action-type" aria-label="Permalink to “Entry Action Type”">​</a></h2><p>Configure how the active spreadsheet entry is treated upon error:</p><h3 id="_1-stop-entry" tabindex="-1">1. Stop Entry <a class="header-anchor" href="#_1-stop-entry" aria-label="Permalink to “1. Stop Entry”">​</a></h3><ul><li>Halts processing for the current row.</li><li>The record is <strong>not</strong> marked as saved.</li><li>Ideal when manual user intervention or debugging is required.</li></ul><h3 id="_2-save-error-in-the-entry-data" tabindex="-1">2. Save Error in the Entry Data <a class="header-anchor" href="#_2-save-error-in-the-entry-data" aria-label="Permalink to “2. Save Error in the Entry Data”">​</a></h3><ul><li>Marks the entry as processed.</li><li>Writes the captured error string into the corresponding spreadsheet record for later review.</li><li>Automatically advances automation to the next data row.</li></ul><hr><h2 id="delay-time-before-run-action" tabindex="-1">Delay Time Before Run Action <a class="header-anchor" href="#delay-time-before-run-action" aria-label="Permalink to “Delay Time Before Run Action”">​</a></h2><p>Specifies a timeout in milliseconds before executing the follow-up recovery action.</p><div class="tip custom-block"><p class="custom-block-title">Conversion</p><p><code>1000 milliseconds = 1 second</code></p></div><hr><h2 id="action" tabindex="-1">Follow-up Action Execution <a class="header-anchor" href="#action" aria-label="Permalink to “Follow-up Action Execution”">​</a></h2><p>Select what occurs once the error state is confirmed:</p><table tabindex="0"><thead><tr><th>Action</th><th>Execution Behavior</th></tr></thead><tbody><tr><td><strong>Redirect to Page</strong></td><td>Navigates the active tab to a recovery URL.</td></tr><tr><td><strong>Re-Execute Form</strong></td><td>Restarts the form workflow from the beginning (useful for transient retries).</td></tr><tr><td><strong>Click on Button</strong></td><td>Dispatches a click on a recovery element (e.g., &quot;Dismiss&quot;, &quot;Close Modal&quot;).</td></tr><tr><td><strong>Page Reload</strong></td><td>Refreshes the active browser tab.</td></tr><tr><td><strong>Execute Segment</strong></td><td>Triggers an error-handling <a href="/documentation/segment.html">Segment</a> routine.</td></tr></tbody></table><hr><h2 id="important-notes" tabindex="-1">Important Execution Rule <a class="header-anchor" href="#important-notes" aria-label="Permalink to “Important Execution Rule”">​</a></h2><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p><strong>Placement Constraint</strong>: When this field executes, <strong>all subsequent fields below it in the form list are bypassed</strong>. Place <strong>Form Error Message</strong> at the very end of your form sequence (or right alongside <code>Current Entry as Saved</code>).</p></div><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Field 1: Username]             ──&gt; Executes</span></span>
<span class="line"><span>[Field 2: Password]             ──&gt; Executes</span></span>
<span class="line"><span>[Field 3: Submit Button]        ──&gt; Executes</span></span>
<span class="line"><span>[Form Error Message]            ──&gt; Detects Error &amp; Handles Recovery</span></span>
<span class="line"><span>--------------------------------------------------------------------</span></span>
<span class="line"><span>[Field 4: Any Lower Field]      ──&gt; DOES NOT EXECUTE (Bypassed)</span></span></code></pre></div><hr><h2 id="use-cases" tabindex="-1">Common Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to “Common Use Cases”">​</a></h2><ul><li><strong>Logging Duplicates</strong>: Automatically mark duplicate records in your <code>.xlsx</code> file and continue batch processing without stopping.</li><li><strong>Handling Transient Timeouts</strong>: Configure <strong>Re-Execute Form</strong> or <strong>Page Reload</strong> to retry forms affected by brief gateway drops.</li><li><strong>Modal Dismissal</strong>: Click modal close buttons automatically when non-blocking warnings appear.</li></ul><hr><h2 id="related" tabindex="-1">Related Documentation <a class="header-anchor" href="#related" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/check.svg" class="doc-icon"> <a href="/documentation/field-types/advance/current-entry-as-saved.html">Current Entry as Saved</a></li><li><img src="/svg/bug.svg" class="doc-icon"> <a href="/documentation/form-response/form-error-response.html">Form Error Response</a></li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/form-fields/field-response-action.html">Field Response Actions</a></li><li><img src="/svg/template.svg" class="doc-icon"> <a href="/documentation/segment.html">Segments Routine Automation</a></li><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template (.xlsx)</a></li></ul>`,62)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};